6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":2531,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 8.28\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T51e,After the student studies the Vedas under the master for some time – at least from age five to twenty – he becomes a man of perfect character. Study of the Vedas is not meant for the recreation of armchair speculators, but for the formation of character. After this training, the brahmacārī is allowed to enter into household life and marry. When he is a householder, he has to perform many sacrifices so that he may achieve further enlightenment. He must also give charity according to the country, time and candidate, discriminating among charity in goodness, in passion and in ignorance, as described in Bhagavad-gītā. Then after retiring from household life, upon accepting the order of vānaprastha, he undergoes severe penances – living in forests, dressing with tree bark, not shaving, etc. By carrying out the orders of brahmacarya, householder life, vānaprastha and finally sannyāsa, one becomes elevated to the perfectional stage of life. Some are then elevated to the heavenly kingdoms, and when they become even more advanced they are liberated in the spiritual sky, either in the impersonal brahma-jyotir or in the Vaikuṇṭha planets or Kṛṣṇaloka. This is the path outlined by Vedic literatures.26:T51f,One who has a little faith in Bhagavad-gītā should learn Bhagavad-gītā from a devotee, because in the beginning of the Fourth Chapter it is stated clearly that Bhagavad-gītā can be understood only by devotees; no one else can perfectly understand the purpose of Bhagavad-gītā. One should therefore learn Bhagavad-gītā from a devotee of Kṛṣṇa, not from mental speculators. This is a sign of faith. When one searches for a devotee and fortunately gets a devotee’s association one actually begins to study and understand Bhagavad-gītā. By advancement in the association of the devotee one is placed in devotional service, and this service dispels all one’s misgivings about Kṛṣṇa, or God, and Kṛṣṇa’s activities, form, pastimes, name and other features. After these misgivings have been perfectly cleared away, one becomes fixed in one’s study. Then one relishes the study of Bhagavad-gītā and attains the state of feeling always Kṛṣṇa conscious. In the advanced stage, one falls completely in love with Kṛṣṇa. This highest perfectional stage of life enables the devotee to be transferred to Kṛṣṇa’s abode in the spiritual sky, Goloka Vṛndāvana, where the devotee becomes eternally happy."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":2531,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"28\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"loca