ath\":\"/nl/library/bg/8/28/\"},{\"display_name\":\"Polski (Polish)\",\"language_code\":\"pl\",\"enabled\":true,\"url_path\":\"/pl/library/bg/8/28/\"},{\"display_name\":\"Português (Portuguese)\",\"language_code\":\"pt-br\",\"enabled\":true,\"url_path\":\"/pt-br/library/bg/8/28/\"},{\"display_name\":\"Русский (Russian)\",\"language_code\":\"ru\",\"enabled\":true,\"url_path\":\"/ru/library/bg/8/28/\"},{\"display_name\":\"Slovenčina (Slovak)\",\"language_code\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/8/28/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/8/28/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/8/28/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/8/\",\"title\":\"Chapter Eight: Attaining the Supreme\"}],\"url_path\":\"/en/library/bg/8/28/\",\"bb\":2240,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/8/27/\",\"title\":\"TEXT 27\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/9/\",\"title\":\"Chapter Nine\",\"has_advanced_view\":true,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":2532,\"bb\":568207,\"url_path\":\"/en/library/bg/8/28/devanagari/\",\"body_final\":\"वेदेषु यज्ञेषु तप:सु चैव
दानेषु यत्पुण्यफलं प्रदिष्टम् ।
अत्येति तत्सर्वमिदं विदित्वा
योगी परं स्थानमुपैति चाद्यम् ॥ २८ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":2533,\"bb\":2241,\"url_path\":\"/en/library/bg/8/28/b2241/\",\"body_value\":\"vedeṣu yajñeṣu tapaḥsu caiva
dāneṣu yat puṇya-phalaṁ pradiṣṭam
atyeti tat sarvam idaṁ viditvā
yogī paraṁ sthānam upaiti cādyam\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":2534,\"bb\":2242,\"url_path\":\"/en/library/bg/8/28/b2242/\",\"shadow_value\":\"vedeṣu – in the study of the Vedas; yajñeṣu – in the performances of yajña, sacrifice; tapaḥsu – in undergoing different types of austerities; ca – also; eva – certainly; dāneṣu – in giving charities; yat – that which; puṇya-phalam – result of pious work; pradiṣṭam – indicated; atyeti – surpasses; tat sarvam – all those; idam – this; viditvā – knowing; yogī – the devotee; param – supreme; sthānam – abode; upaiti – achieves; ca – also; ādyam – original.\",\"word_for_word_value\":[{\"word\":\"vedeṣu\",\"translation\":\"in the study of the Vedas\"},{\"word\":\"yajñeṣu\",\"translation\":\"in the performances of yajña, sacrifice\"},{\"word\":\"tapaḥsu\",\"translation\":\"in undergoing different types of austerities\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"eva\",\"translation\":\"certainly\"},{\"word\":\"dāneṣu\",\"translation\":\"in giving charities\"},{\"word\":\"yat\",\"translation\":\"that which\"},{\"word\":\"puṇya-phalam\",\"translation\":\"result of pious work\"},{\"word\":\"pradiṣṭam\",\"translation\":\"indicated\"},{\"word\":\"atyeti\",\"translation\":\"surpasses\"},{\"word\":\"tat sarvam\",\"translation\":\"all those\"},{\"word\":\"idam\",\"translation\":\"this\"},{\"word\":\"viditvā\",\"translation\":\"knowing\"},{\"word\":\"yogī\",\"translation\":\"the devotee\"},{\"word\":\"param\",\"translation\":\"supreme\"},{\"word\":\"sthānam\",\"translation\":\"abode\"},{\"word\":\"upaiti\",\"translation\":\"achieves\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"ādyam\",\"translation\":\"original\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":2535,\"bb\":2243,\"url_path\":\"/en/library/bg/8/28/b2243/\",\"body_value\":\"A person who accepts the path of devotional service is not bereft of the results derived from studying the Vedas, performing sacrifices, undergoing austerities, giving charity or pursuing philosophical and fruitive activities. Simply by performing devotional service, he attains all these, and at the end he reaches the supreme eternal abode.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2536,\"bb\":2244,\"url_path\":\"/en/library/bg/8/28/b2244/\",\"body_value\":\"This verse is the summation of the Seventh and Eighth chapters, which particularly deal with Kṛṣṇa consciousness and devotional service. One has to study the Vedas under the guidance of the spiritual master and undergo many austerities and penances while living under his care. A brahmacārī has to live in the home of the spiritual master just like a servant, and he must beg alms from door to door and bring them to the spiritual master. He takes food only under the master’s order, and if the master neglects to call the student for food that day, the student fasts. These are some of the Vedic principles for observing brahmacarya.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2537,\"bb\":2245,\"url_path\":\"/en/library/bg/8/28/b2245/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2538,\"bb\":2246,\"url_path\":\"/en/library/bg/8/28/b2246/\",\"body_value\":\"The beauty of Kṛṣṇa consciousness, however, is that by one stroke, by engaging in devotional service, one can surpass all the rituals of the different orders of life.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2539,\"bb\":2247,\"url_path\":\"/en/library/bg/8/28/b2247/\",\"body_value\":\"The words idaṁ viditvā indicate that one should understand the instructions given by Śrī Kṛṣṇa in this chapter and the Seventh Chapter of Bhagavad-gītā. One should try to understand these chapters not by scholarship or mental speculation but by hearing them in association with devotees. Chapters Seven through Twelve are the essence of Bhagavad-gītā. The first six and the last six chapters are like coverings for the middle six chapters, which are especially protected by the Lord. If one is fortunate enough to understand Bhagavad-gītā – especially these middle six chapters – in the association of devotees, then his life at once becomes glorified beyond all penances, sacrifices, charities, speculations, etc., for one can achieve all the results of these activities simply by Kṛṣṇa consciousness.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2540,\"bb\":2248,\"url_path\":\"/en/library/bg/8/28/b2248/\",\"body_value\":\"$26\"},{\"type\":\"content.Record\",\"title\":\"paragraph_end\",\"id\":2541,\"bb\":2249,\"url_path\":\"/en/library/bg/8/28/b2249/\",\"body_value\":\"Thus end the Bhaktivedanta Purports to the Eighth Chapter of the Śrīmad Bhagavad-gītā in the matter of Attaining the Supreme. \"}]}],\"short_title\":\"Bg. 8.28\",\"medium_title\":\"Bhagavad-gītā As It Is 8.28\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L27\",\"$L28\",\"$L29\"]}]\n"])self.__next_f.push([1,"2b:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n31:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5