_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":2543,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 9.1\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T451,The very beginning of Bhagavad-gītā, the First Chapter, is more or less an introduction to the rest of the book; and in the Second and Third chapters, the spiritual knowledge described is called confidential. Topics discussed in the Seventh and Eighth chapters are specifically related to devotional service, and because they bring enlightenment in Kṛṣṇa consciousness, they are called more confidential. But the matters which are described in the Ninth Chapter deal with unalloyed, pure devotion. Therefore this is called the most confidential. One who is situated in the most confidential knowledge of Kṛṣṇa is naturally transcendental; he therefore has no material pangs, although he is in the material world. In the Bhakti-rasāmṛta-sindhu it is said that although one who has a sincere desire to render loving service to the Supreme Lord is situated in the conditional state of material existence, he is to be considered liberated. Similarly, we shall find in the Bhagavad-gītā, Tenth Chapter, that anyone who is engaged in that way is a liberated person."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":2543,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"1\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 1\",\"advanced_view_url_path\":\"/en/library/bg/9/advanced-view/#bb2252\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/9/1/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/9/1/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/9/1/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/9/1/\"},{\"display_name\":\"English\",\"language_code\":\"en\",\"enabled\":true,\"url_path\":\"/en/library/bg/9/1/\"},{\"display_name\":\"Español (Spanish)\",\"language_code\":\"es\",\"enabled\":true,\"url_path\":\"/es/library/bg/9/1/\"},{\"display_name\":\"Eesti keel (Estonian)\",\"language_code\":\"et\",\"enabled\":true,\"url_path\":\"/et/library/bg/9/1/\"},{\"display_name\":\"Suomen kieli (Finnish)\",\"language_code\":\"fi\",\"enabled\":false,\"url_path\":\"/fi/\"},{\"display_name\":\"Français (French)\",\"language_code\":\"fr\",\"enabled\":true,\"url_path\":\"/fr/library/bg/9/1/\"},{\"display_name\":\"Hrvatski (Croatian)\",\"language_code\":\"hr\",\"enabled\":true,\"url_path\":\"/hr/library/bg/9/1/\"},{\"display_name\":\"Magyar (Hungarian)\",\"language_code\":\"hu\",\"enabled\":true,\"url_path\":\"/hu/library/bg/9/1/\"},{\"display_name\":\"日本語 (Japanese)\",\"language_code\":\"ja\",\"enabled\":true,\"url_path\":\"/ja/library/bg/9/1/\"},{\"display_name\":\"한국어 (Korean)\",\"language_code\":\"ko\",\"enabled\":true,\"url_path\":\"/ko/library/bg/9/1/\"},{\"display_name\":\"Lietuvių kalba (Lithuanian)\",\"language_code\":\"lt\",\"enabled\":true,\"url_path\":\"/lt/library/bg/9/1/\"},{\"display_name\":\"Nederlands (Dutch)\",\"language_code\":\"nl\",\"enabled\":true,\"url_path\":\"/nl/library/bg/9/1/\"},{\"display_name\":\"Polski (Polish)\",\"language_code\":\"pl\",\"enabled\":true,\"url_path\":\"/pl/library/bg/9/1/\"},{\"display_name\":\"Português (Portuguese)\",\"language_code\":\"pt-br\",\"enabled\":true,\"url_path\":\"/pt-br/library/bg/9/1/\"},{\"display_name\":\"Русский (Russian)\",\"language_code\":\"ru\",\"enabled\":true,\"url_path\":\"/ru/library/bg/9/1/\"},{\"display_name\":\"Slovenčina (Slovak)\",\"language_code\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/9/1/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/9/1/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/9/1/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/9/\",\"title\":\"Chapter Nine: The Most Confidential Knowledge\"}],\"url_path\":\"/en/library/bg/9/1/\",\"bb\":2252,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/9/\",\"title\":\"Chapter Nine\",\"has_advanced_view\":true,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/9/2/\",\"title\":\"TEXT 2\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":2544,\"bb\":568208,\"url_path\":\"/en/library/bg/9/1/devanagari/\",\"body_final\":\"श्रीभगवानुवाच
इदं तु ते गुह्यतमं प्रवक्ष्याम्यनसूयवे ।
ज्ञानं विज्ञानसहितं यज्ज्ञात्वा मोक्ष्यसेऽश‍ुभात् ॥ १ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":2545,\"bb\":2254,\"url_path\":\"/en/library/bg/9/1/b2254/\",\"body_value\":\"śrī-bhagavān uvāca
idaṁ tu te guhya-tamaṁ
pravakṣyāmy anasūyave
jñānaṁ vijñāna-sahitaṁ
yaj jñātvā mokṣyase ’śubhāt\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":2546,\"bb\":2255,\"url_path\":\"/en/library/bg/9/1/b2255/\",\"shadow_value\":\"śrī-bhagavān uvāca – the Supreme Personality of Godhead said; idam – this; tu – but; te – unto you; guhya-tamam – the most confidential; pravakṣyāmi – I am speaking; anasūyave – to the nonenvious; jñānam – knowledge; vijñāna – realized knowledge; sahitam – with; yat – which; jñātvā – knowing; mokṣyase – you will be released; aśubhāt – from this miserable material existence.\",\"word_for_word_value\":[{\"word\":\"śrī-bhagavān uvāca\",\"translation\":\"the Supreme Personality of Godhead said\"},{\"word\":\"idam\",\"translation\":\"this\"},{\"word\":\"tu\",\"translation\":\"but\"},{\"word\":\"te\",\"translation\":\"unto you\"},{\"word\":\"guhya-tamam\",\"translation\":\"the most confidential\"},{\"word\":\"pravakṣyāmi\",\"translation\":\"I am speaking\"},{\"word\":\"anasūyave\",\"translation\":\"to the nonenvious\"},{\"word\":\"jñānam\",\"translation\":\"knowledge\"},{\"word\":\"vijñāna\",\"translation\":\"realized knowledge\"},{\"word\":\"sahitam\",\"translation\":\"with\"},{\"word\":\"yat\",\"translation\":\"which\"},{\"word\":\"jñātvā\",\"translation\":\"knowing\"},{\"word\":\"mokṣyase\",\"translation\":\"you will be released\"},{\"word\":\"aśubhāt\",\"translation\":\"from this miserable material existence\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":2547,\"bb\":2256,\"url_path\":\"/en/library/bg/9/1/b2256/\",\"body_value\":\"The Supreme Personality of Godhead said: My dear Arjuna, because you are never envious of Me, I shall impart to you this most confidential knowledge and realization, knowing which you shall be relieved of the miseries of material existence.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2548,\"bb\":2257,\"url_path\":\"/en/library/bg/9/1/b2257/\",\"body_value\":\"As a devotee hears more and more about the Supreme Lord, he becomes enlightened. This hearing process is recommended in the Śrīmad-Bhāgavatam: “The messages of the Supreme Personality of Godhead are full of potencies, and these potencies can be realized if topics regarding the Supreme Godhead are discussed amongst devotees.” This cannot be achieved by the association of mental speculators or academic scholars, for it is realized knowledge.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2549,\"bb\":2258,\"url_path\":\"/en/library/bg/9/1/b2258/\",\"body_value\":\"The devotees are constantly engaged in the Supreme Lord’s service. The Lord understands the mentality and sincerity of a particular living entity who is engaged in Kṛṣṇa consciousness and gives him the intelligence to understand the science of Kṛṣṇa in the association of devotees. Discussion of Kṛṣṇa is very potent, and if a fortunate person has such association and tries to assimilate the knowledge, then he will surely make advancement toward spiritual realization. Lord Kṛṣṇa, in order to encourage Arjuna to higher and higher elevation in His potent service, describes in this Ninth Chapter matters more confidential than any He has already disclosed.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2550,\"bb\":2259,\"url_path\":\"/en/library/bg/9/1/b2259/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2551,\"bb\":2260,\"url_path\":\"/en/library/bg/9/1/b2260/\",\"body_value\":\"Now this first verse has specific significance. The words idaṁ jñānam (“this knowledge”) refer to pure devotional service, which consists of nine different activities: hearing, chanting, remembering, serving, worshiping, praying, obeying, maintaining friendship and surrendering everything. By the practice of these nine elements of devotional service one is elevated to spiritual consciousness, Kṛṣṇa consciousness. When one’s heart is thus cleared of material contamination, one can understand this science of Kṛṣṇa. Simply to understand that a living entity is not material is not sufficient. That may be the beginning of spiritual realization, but one should recognize the difference between activities of the body and the spiritual activities of one who understands that he is not the body.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2552,\"bb\":2261,\"url_path\":\"/en/library/bg/9/1/b2261/\",\"body_value\":\"In the Seventh Chapter we have already discussed the opulent potency of the Supreme Personality of Godhead, His different energies, the inferior and superior natures, and all this material manifestation. Now in Chapter Nine the glories of the Lord will be delineated.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2553,\"bb\":2262,\"url_path\":\"/en/library/bg/9/1/b2262/\",\"body_value\":\"The Sanskrit word anasūyave in this verse is also very significant. Generally the commentators, even if they are highly scholarly, are all envious of Kṛṣṇa, the Supreme Personality of Godhead. Even the most erudite scholars write on Bhagavad-gītā very inaccurately. Because they are envious of Kṛṣṇa, their commentaries are useless. The commentaries given by devotees of the Lord are bona fide. No one can explain Bhagavad-gītā or give perfect knowledge of Kṛṣṇa if he is envious. One who criticizes the character of Kṛṣṇa without knowing Him is a fool. So such commentaries should be very carefully avoided. For one who understands that Kṛṣṇa is the Supreme Personality of Godhead, the pure and transcendental Personality, these chapters will be very beneficial.\"}]}],\"short_title\":\"Bg. 9.1\",\"medium_title\":\"Bhagavad-gītā As It Is 9.1\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L26\",\"$L27\",\"$L28\"]}]\n"])self.__n