_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":2554,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 9.2\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T486,The Bhagavad-gītā, especially from the Second Chapter on, stresses the importance of the soul. In the very beginning, the Lord says that this body is perishable and that the soul is not perishable (antavanta ime dehā nityasyoktāḥ śarīriṇaḥ). That is a confidential part of knowledge: simply knowing that the spirit soul is different from this body and that its nature is immutable, indestructible and eternal. But that gives no positive information about the soul. Sometimes people are under the impression that the soul is different from the body and that when the body is finished, or one is liberated from the body, the soul remains in a void and becomes impersonal. But actually that is not the fact. How can the soul, which is so active within this body, be inactive after being liberated from the body? It is always active. If it is eternal, then it is eternally active, and its activities in the spiritual kingdom are the most confidential part of spiritual knowledge. These activities of the spirit soul are therefore indicated here as constituting the king of all knowledge, the most confidential part of all knowledge.26:T441,This knowledge is the purest form of all activities, as explained in Vedic literature. In the Padma Purāṇa, man’s sinful activities have been analyzed and are shown to be the results of sin after sin. Those who are engaged in fruitive activities are entangled in different stages and forms of sinful reactions. For instance, when the seed of a particular tree is sown, the tree does not appear immediately to grow; it takes some time. It is first a small, sprouting plant, then it assumes the form of a tree, then it flowers and bears fruit, and, when it is complete, the flowers and fruits are enjoyed by persons who have sown the seed of the tree. Similarly, a man performs a sinful act, and like a seed it takes time to fructify. There are different stages. The sinful action may have already stopped within the individual, but the results or the fruit of that sinful action are still to be enjoyed. There are sins which are still in the form of a seed, and there are others which are already fructified and are giving us fruit, which we are enjoying as distress and pain.27:T594,"])self.__next_f.push([1,"The word dharmyam means “the path of religion.” Nārada was actually a son of a maidservant. He had no opportunity to go to school. He was simply assisting his mother, and fortunately his mother rendered some service to the devotees. The child Nārada also got the opportunity and simply by association achieved the highest goal of all religion. The highest goal of all religion is devotional service, as stated in Śrīmad-Bhāgavatam (sa vai puṁsāṁ paro dharmo yato bhaktir adhokṣaje). Religious people generally do not know that the highest perfection of religion is the attainment of devotional service. As we have already discussed in regard to the last verse of Chapter Eight (vedeṣu yajñeṣu tapaḥsu caiva), generally Vedic knowledge is required for self-realization. But here, although Nārada never went to the school of the spiritual master and was not educated in the Vedic principles, he acquired the highest results of Vedic study. This process is so potent that even without performing the religious process regularly, one can be raised to the highest perfection. How is this possible? This is also confirmed in Vedic literature: ācāryavān puruṣo veda. One who is in association with great ācāryas, even if he is not educated or has never studied the Vedas, can become familiar with all the knowledge necessary for realization."])self.__next_f.push([1,"28:T4e8,The process of devotional service is a very happy one (su-sukham). Why? Devotional service consists of śravaṇaṁ kīrtanaṁ viṣṇoḥ, so one can simply hear the chanting of the glories of the Lord or can attend philosophical lectures on transcendental knowledge given by authorized ācāryas. Simply by sitting, one can learn; then one can eat the remnants of the food offered to God, nice palatable dishes. In every state devotional service is joyful. One can execute devotional service even in the most poverty-stricken condition. The Lord says, patraṁ puṣpaṁ phalaṁ toyam: He is ready to accept from the devotee any kind of offering, never mind what. Even a leaf, a flower, a bit of fruit, or a little water, which are all available in every part of the world, can be offered by any person, regardless of social position, and will be accepted if offered with love. There are many instances in history. Simply by tasting the tulasī leaves offered to the lotus feet of the Lord, great sages like Sanat-kumāra became great devotees. Therefore the devotional process is very nice, and it can be executed in a happy mood. God accepts only the love with which things are offered to Him.29:T55c,As will be seen in Bhagavad-gītā, actual devotional service begins after liberation. After one is liberated, when one is situated in the Brahman position (brahma-bhūta), one’s devotional service begins (samaḥ sarveṣu bhūteṣu mad-bhaktiṁ labhate parām). No one can understand the Supreme Personality of Godhead by executing karma-yoga, jñāna-yoga, aṣṭāṅga-yoga or any other yoga independently. By these yogic methods one may make a little progress toward bhakti-yoga, but without coming to the stage of devotional service one cannot understand what is the Personality of Godhead. In the Śrīmad-Bhāgavatam it is also confirmed that when one becomes purified by executing the process of devotional service, especially by hearing Śrīmad-Bhāgavatam or Bhagavad-gītā from realized souls, then he can understand the science of Kṛṣṇa, or the science of God. Evaṁ prasanna-manaso bhagavad-bhakti-yogataḥ. When one’s heart is cleared of all nonsense, then one can understand what God is. Thus the process of devotional service, of Kṛṣṇa consciousness, is the king of all education and the king of all confidential knowledge. It is the purest form of religion, and it can be executed joyfully without difficulty. Therefore one should adopt it."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":2554,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"2\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 2\",\"advanced_view_url_path\":\"/en/library/bg/9/advanced-view/#bb2263\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/9/2/\"},{\"display_name\":\"Če