_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":2576,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 9.3\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:Tbf7,"])self.__next_f.push([1,"Now, the development of that faith is the process of Kṛṣṇa consciousness. There are three divisions of Kṛṣṇa conscious men. In the third class are those who have no faith. Even if they are officially engaged in devotional service, they cannot achieve the highest perfectional stage. Most probably they will slip, after some time. They may become engaged, but because they haven’t complete conviction and faith, it is very difficult for them to continue in Kṛṣṇa consciousness. We have practical experience in discharging our missionary activity that some people come and apply themselves to Kṛṣṇa consciousness with some hidden motive, and as soon as they are economically a little well situated they give up this process and take to their old ways again. It is only by faith that one can advance in Kṛṣṇa consciousness. As far as the development of faith is concerned, one who is well versed in the literatures of devotional service and has attained the stage of firm faith is called a first-class person in Kṛṣṇa consciousness. And in the second class are those who are not very advanced in understanding the devotional scriptures but who automatically have firm faith that kṛṣṇa-bhakti, or service to Kṛṣṇa, is the best course and so in good faith have taken it up. Thus they are superior to the third class, who have neither perfect knowledge of the scriptures nor good faith but by association and simplicity are trying to follow. The third-class person in Kṛṣṇa consciousness may fall down, but when one is in the second class he does not fall down, and for the first-class person in Kṛṣṇa consciousness there is no chance of falling down. One in the first class will surely make progress and achieve the result at the end. As far as the third-class person in Kṛṣṇa consciousness is concerned, although he has faith in the conviction that devotional service to Kṛṣṇa is very good, he has not yet gained adequate knowledge of Kṛṣṇa through the scriptures like Śrīmad-Bhāgavatam and Bhagavad-gītā. Sometimes these third-class persons in Kṛṣṇa consciousness have some tendency toward karma-yoga and jñāna-yoga, and sometimes they are disturbed, but as soon as the infection of karma-yoga or jñāna-yoga is vanquished, they become second-class or first-class persons in Kṛṣṇa consciousness. Faith in Kṛṣṇa is also divided into three stages and described in Śrīmad-Bhāgavatam. First-class attachment, second-class attachment and third-class attachment are also explained in Śrīmad-Bhāgavatam in the Eleventh Canto. Those who have no faith even after hearing about Kṛṣṇa and the excellence of devotional service, who think that it is simply eulogy, find the path very difficult, even if they are supposedly engaged in devotional service. For them there is very little hope of gaining perfection. Thus faith is very important in the discharge of devotional service."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":2576,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"3\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 3\",\"advanced_view_url_path\":\"/en/library/bg/9/advanced-view/#bb2284\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/9/3/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/9/3/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/9/3/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/9/3/\"},{\"display_name\":\"English\",\"language_code\":\"en\",\"enabled\":true,\"url_path\":\"/en/library/bg/9/3/\"},{\"display_name\":\"Español (Spanish)\",\"language_code\":\"es\",\"enabled\":true,\"url_path\":\"/es/library/bg/9/3/\"},{\"display_name\":\"Eesti keel (Estonian)\",\"language_code\":\"et\",\"enabled\":true,\"url_path\":\"/et/library/bg/9/3/\"},{\"display_name\":\"Suomen kieli (Finnish)\",\"language_code\":\"fi\",\"enabled\":false,\"url_path\":\"/fi/\"},{\"display_name\":\"Français (French)\",\"language_code\":\"fr\",\"enabled\":true,\"url_path\":\"/fr/library/bg/9/3/\"},{\"display_name\":\"Hrvatski (Croatian)\",\"language_code\":\"hr\",\"enabled\":true,\"url_path\":\"/hr/library/bg/9/3/\"},{\"display_name\":\"Magyar (Hungarian)\",\"language_code\":\"hu\",\"enabled\":true,\"url_path\":\"/hu